kamyu-c-reorder-list-0ex7acw:
// Time:  O(n)
// Space: O(1)

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode(int x) : val(x), next(NULL) {}
 * };
 */
class Solution {
    public:
        void reorderList(ListNode *head) {
        if (!head) {
            return;
        }

        auto slow = head, fast = head;

        while (fast->next && fast->next->next) {
            slow = slow->next;
            fast = fast->next->next;
        }

        // Split into two lists.
        auto tmp = slow->next;
        slow->next = nullptr;
        slow = tmp;

        merge(head, reverse(slow));
    }

private:
    ListNode *reverse(ListNode *head) {
        ListNode dummy{0};

        while (head) {
            auto tmp = head->next;
            head->next = dummy.next;
            dummy.next = head;
            head = tmp;
        }

        return dummy.next;
    }

    ListNode *merge(ListNode *list1, ListNode *list2) {
        ListNode dummy{0};
        auto ptr = &dummy;

        while (list1 && list2) {
            auto tmp = list1->next;

            ptr->next = list1;
            ptr = ptr->next;
            ptr->next = list2;
            ptr = ptr->next;

            list1 = tmp;
            list2 = list2->next;
        }

        if (list1) {
            ptr->next = list1;
        }

        return dummy.next;
    }
};

kamyu-c-reorder-log-files-1aam8vu:
// Time:  O(nlogn * l), n is the length of files, l is the average length of strings
// Space: O(l)

class Solution {
public:
    vector<string> reorderLogFiles(vector<string>& logs) {
        auto pivot = stable_partition(logs.begin(), logs.end(),
                                      []( const auto& log ) {
                                          return isalpha(log.back());
                                      });
        sort(logs.begin(), pivot,
             [](const auto& a, const auto& b) {
                 int i = a.find_first_of(' '), j = b.find_first_of(' ');
                 return a.substr(i) != b.substr(j) ?
                            a.substr(i) < b.substr(j) :
                            a.substr(0, i) < b.substr(0, j);
             });
        return logs;
    }
};

kamyu-c-reorder-routes-to-make-all-paths:
// Time:  O(n)
// Space: O(n)

class Solution {
public:
    int minReorder(int n, vector<vector<int>>& connections) {
        unordered_set<uint64_t> lookup;
        unordered_map<int, vector<int>> graph;
        for (const auto& connection : connections) {
            lookup.emplace(uint64_t(connection[0]) * n + connection[1]);
            graph[connection[0]].emplace_back(connection[1]);
            graph[connection[1]].emplace_back(connection[0]);
        }
        int result = 0;
        vector<pair<int, int>> stk = {{-1, 0}};
        while (!stk.empty()) {
            const auto [parent, u] = stk.back(); stk.pop_back();
            for (const auto& v : graph[u]) {
                if (v == parent) {
                    continue;
                }
                stk.emplace_back(u, v);
            }
            result += lookup.count(uint64_t(parent) * n + u);
        }
        return result;
    }
};

// Time:  O(n)
// Space: O(n)
class Solution2 {
public:
    int minReorder(int n, vector<vector<int>>& connections) {
        unordered_set<uint64_t> lookup;
        unordered_map<int, vector<int>> graph;
        for (const auto& connection : connections) {
            lookup.emplace(uint64_t(connection[0]) * n + connection[1]);
            graph[connection[0]].emplace_back(connection[1]);
            graph[connection[1]].emplace_back(connection[0]);
        }
        return dfs(n, lookup, graph, -1, 0);
    }

private:
    int dfs(int n, const unordered_set<uint64_t>& lookup, const unordered_map<int, vector<int>>& graph, int parent, int u) {
        int result = lookup.count(uint64_t(parent) * n + u);
        for (const auto& v : graph.at(u)) {
            if (v == parent) {
                continue;
            }
            result += dfs(n, lookup, graph, u, v);
        }
        return result;
    }
};

