// Time:  O((logn)^2) = O(1) due to n is a 32-bit number
// Space: O(logn) = O(1)

class Solution {
public:
    bool reorderedPowerOf2(int N) {
        vector<int> count = counter(N);
        for (int i = 0; i < 31; ++i) {
            if (count == counter(1 << i)) {
                return true;
            }
        }
        return false;
    }

private:
    vector<int> counter(int N) {
        vector<int> result(10, 0);
        for (; N; N /= 10) {
            ++result[N % 10];
        }
        return result;
    }
};

kamyu-c-reorganize-string-1b7z20u:
// Time:  O(nloga) = O(n), a is the size of alphabet
// Space: O(a) = O(1)

class Solution {
public:
    string reorganizeString(string S) {
        unordered_map<char, int> counts;
        for (const auto& c : S) {
            ++counts[c];
        }
        if (any_of(counts.cbegin(), counts.cend(),
                  [&](const pair<char, int>& kvp) { 
                      return kvp.second > (S.length() + 1) / 2;
                  })) {
            return "";
        }

        string result;
        priority_queue<pair<int, char>> max_heap;
        for (const auto& kvp : counts) {
            max_heap.emplace(kvp.second, kvp.first);
        }
        while (max_heap.size() > 1) {
            char c1, c2;
            int count1, count2;
            tie(count1, c1) = max_heap.top(); max_heap.pop();
            tie(count2, c2) = max_heap.top(); max_heap.pop();
            if (result.empty() || c1 != result.back()) {
                result.push_back(c1);
                result.push_back(c2);
                if (count1 - 1 > 0) {
                    max_heap.emplace(count1 - 1, c1);
                }
                if (count2 - 1 > 0) {
                    max_heap.emplace(count2 - 1, c2);
                }
            }
        }
        return max_heap.empty() ? result : result + max_heap.top().second;
    }
};

kamyu-c-repeated-string-match-0rrsz7o:
// Time:  O(n + m)
// Space: O(1)

// Rabin-Karp Algorithm (rolling hash)
class Solution {
public:
    int repeatedStringMatch(string A, string B) {
        static const uint64_t M = 1000000007;
        static const uint64_t p = 113; 
        static const uint64_t p_inv = pow(p, M - 2, M);

        const auto q = (B.length() + A.length() - 1) / A.length();

        uint64_t b_hash = 0, power = 1;
        for (int i = 0; i < B.length(); ++i) {
            b_hash += power * B[i];
            b_hash %= M;
            power = (power * p) % M;
        }

        uint64_t a_hash = 0; power = 1;
        for (int i = 0; i < B.length(); ++i) {
            a_hash += power * A[i % A.length()];
            a_hash %= M;
            power = (power * p) % M;
        }
        if (a_hash == b_hash && check(0, A, B)) {
            return q;
        }

        power = (power * p_inv) % M;
        for (int i = B.length(); i < (q + 1) * A.length(); ++i) {
            a_hash -= A[(i - B.length()) % A.length()];
            a_hash *= p_inv;
            a_hash += power * A[i % A.length()];
            a_hash %= M;
            if (a_hash == b_hash && check(i - B.length() + 1, A, B)) {
                return i < q * A.length() ? q : q + 1;
            }
        }
        return -1;
    }

private:
    bool check(int index, const string& A, const string& B) {
        for (int i = 0; i < B.length(); ++i) {
            if (A[(i + index) % A.length()] != B[i]) {
                return false;
            }
        }
        return true;
    }

    uint64_t pow(uint64_t a,uint64_t b, uint64_t m) {
        a %= m;
        uint64_t result = 1;
        while (b) {
            if (b & 1) {
                result = (result * a) % m;
            }
            a = (a * a) % m;
            b >>= 1;
        }
        return result;
    }
};

kamyu-c-repeated-substring-pattern-1h8q8:
// Time:  O(n)
// Space: O(n)

// KMP solution.
class Solution {
public:
    bool repeatedSubstringPattern(string str) {
        vector<int> prefix = getPrefix(str);
        return prefix.back() != -1 &&
               (prefix.back() + 1) % (str.length() - prefix.back() - 1) == 0;
    }

private:
    vector<int> getPrefix(const string& pattern) {
        vector<int> prefix(pattern.length(), -1);
        int j = -1;
        for (int i = 1; i < pattern.length(); ++i) {
            while (j > -1 && pattern[j + 1] != pattern[i]) {
                j = prefix[j];
            }
            if (pattern[j + 1] == pattern[i]) {
                ++j;
            }
            prefix[i] = j;
        }
        return prefix;
    }
};

