kamyu-c-replace-the-substring-for-balanc:
// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int balancedString(string s) {
        unordered_map<int, int> count;
        for (const auto& c : s) {
            ++count[c];
        }
        int result = s.length();
        int left = 0;
        for (int right = 0; right < s.length(); ++right) {
            --count[s[right]];
            while (left < s.length() &&
                   all_of(count.cbegin(), count.cend(),
                          [&s](const auto& kvp) {
                              return kvp.second <= s.length() / 4;
                          })) {
                result = min(result, right - left + 1);
                ++count[s[left++]];
            }
        }
        return result;
    }
};

kamyu-c-replace-words-1huyu9c:
// Time:  O(n)
// Space: O(t), t is the number of nodes in trie

class Solution {
public:
    string replaceWords(vector<string>& dict, string sentence) {
        TrieNode trie;
        string result;
        for (const auto& s : dict) {
            trie.Insert(s);
        }
        auto curr = &trie;
        for (const auto& c : sentence) {
            if (c == ' ' || !curr || !curr->isString) {
                result += c;
            }
            if (c == ' ') {
                curr = &trie;
            } else if (curr && !curr->isString) {
                curr = curr->leaves[c];
            }
        }
        return result;
    }

private:
    struct TrieNode {
        bool isString = false;
        unordered_map<char, TrieNode *> leaves;

        void Insert(const string& s) {
            auto* p = this;
            for (const auto& c : s) {
                if (p->leaves.find(c) == p->leaves.cend()) {
                    p->leaves[c] = new TrieNode;
                }
                p = p->leaves[c];
            }
            p->isString = true;
        }

        ~TrieNode() {
            for (auto& kv : leaves) {
                if (kv.second) {
                    delete kv.second;
                }
            }
        }
    };
};

