            return result;
        };

        for (int i = 0, l = 0, cnt = -1; i < size(s); ++i) {
            if (s[i] == ' ') {
                l = 0;
                continue;
            }
            ++l;
            if (i + 1 != size(s) && s[i + 1] != ' ') {
                continue;
            }
            const auto& c = count(i - l + 1, i);
            if (cnt == -1) {
                cnt = c;
            } else if (cnt == c) {
                reverse(begin(s) + i - l + 1, begin(s) + (i + 1));
            }
        }
        return s;
    }
};

