            for (int i = 0; i < mn; ++i) {
                cnt2 += get(i, j);
            }
            for (int i = 0; i < mn; ++i) {
                if (get(i, j)) {
                    result += (cnt1[i] - 1ll) * (cnt2 - 1ll);
                }
            }
        }
        return result;
    }
};

