/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    int findSecondMinimumValue(TreeNode* root) {
        set<int> bst;
        findSecondMinimumValueHelper(root, &bst);
        if (bst.size() < 2) {
            return -1;
        } 
        return *bst.rbegin();
    }

private:
    void findSecondMinimumValueHelper(TreeNode* root, set<int> *bst) {
        if (!root) {
            return;
        }
        bst->emplace(root->val);
        if (bst->size() > 2) {
            bst->erase(prev(bst->end()));
        }
        findSecondMinimumValueHelper(root->left, bst);
        findSecondMinimumValueHelper(root->right, bst);
    }
};

kamyu-c-second-minimum-time-to-reach-des:
// Time:  O(|V| + |E|) = O(|E|) since graph is connected, O(|E|) >= O(|V|)
// Space: O(|V| + |E|) = O(|E|)

class Solution {
public:
    int secondMinimum(int n, vector<vector<int>>& edges, int time, int change) {
        vector<vector<int>> adj(n);
        for (const auto& edge : edges) {
            adj[edge[0] - 1].emplace_back(edge[1] - 1);
            adj[edge[1] - 1].emplace_back(edge[0] - 1);
        }
        return calc_time(time, change, bi_bfs(adj, 0, n - 1));
    }

private:
    // Template:
    // https://github.com/kamyu104/LeetCode-Solutions/blob/master/C++/nearest-exit-from-entrance-in-maze.cpp
    int bi_bfs(const vector<vector<int>>& adj, int start, int end) {
        unordered_set<int> left = {start}, right = {end}, lookup;
        int result = 0, steps = 0;
        while (!empty(left) && (!result || result + 2 > steps)) {  // modified
            for (const auto& u : left) {
                lookup.emplace(u);
            }
            unordered_set<int> new_left;
            for (const auto& u : left) {
                if (right.count(u)) {
                    if (!result) {  // modified
                        result = steps;
                    } else if (result < steps) {  // modified
                        return result + 1;
                    }
                }
                for (const auto& v : adj[u]) {
                    if (lookup.count(v)) {
                        continue;
                    }
                    new_left.emplace(v);
                }
            }
            left = move(new_left);
            ++steps;
            if (size(left) > size(right)) {
                swap(left, right);
            }
        }
        return result + 2;  // modified
    }

    int calc_time(int time, int change, int dist) {
        int result = 0;
        while (dist--) {
            if (result / change % 2) {
                result = (result / change + 1) * change;
            }
            result += time;
        }
        return result;
    }
};

// Time:  O(|V| + |E|) = O(|E|) since graph is connected, O(|E|) >= O(|V|) 
// Space: O(|V| + |E|) = O(|E|)
class Solution2 {
public:
    int secondMinimum(int n, vector<vector<int>>& edges, int time, int change) {
        vector<vector<int>> adj(n);
        for (const auto& edge : edges) {
            adj[edge[0] - 1].emplace_back(edge[1] - 1);
            adj[edge[1] - 1].emplace_back(edge[0] - 1);
        }
        const auto& dist_to_end = bfs(adj, 0);
        const auto& dist_to_start = bfs(adj, n - 1);
        int dist = dist_to_end[n - 1] + 2;  // always exists
        for (int i = 0; i < n; ++i) {
            if (dist_to_end[i] + dist_to_start[i] == dist_to_end[n - 1]) {
                continue;
            }
            dist = min(dist, dist_to_end[i] + dist_to_start[i]);  // find second min
            if (dist == dist_to_end[n - 1] + 1) {
                break;
            }
        }
        return calc_time(time, change, dist);
    }

private:
    vector<int> bfs(const vector<vector<int>>& adj, int start) {
        static const int INF = numeric_limits<int>::max();
        vector<int> q = {start};
        vector<int> dist(size(adj), INF);
        dist[start] = 0;
        while (!empty(q)) {
            vector<int> new_q;
            for (const auto& u : q) {
                for (const auto& v: adj[u]) {
                    if (dist[v] != INF) {
                        continue;
                    }
                    dist[v] = dist[u] + 1;
                    new_q.emplace_back(v);
                }
            }
            q = move(new_q);
        }
        return dist;
    }

    int calc_time(int time, int change, int dist) {
        int result = 0;
        while (dist--) {
            if (result / change % 2) {
                result = (result / change + 1) * change;
            }
            result += time;
        }
        return result;
    }
};

kamyu-c-select-cells-in-grid-with-maximu:
// Time:  O(n^2 * max(n, r)), r = max(x for row in grid for x in row)
// Space: O(n * max(n, r))

// hungarian algorithm, weighted bipartite matching
class Solution {
public:
    int maxScore(vector<vector<int>>& grid) {
        int mx = 0;
        for (const auto& row : grid) {
            mx = max(mx, ranges::max(row));
        }
        vector<vector<int>> adj(size(grid), vector<int>(max(mx, static_cast<int>(size(grid)))));
        for (int i = 0; i < size(grid); ++i) {
            for (const auto& x : grid[i]) {
                adj[i][x - 1] = -x;
            }
        }
        return -hungarian(adj).first;
    }

private:
    // Template modified from:
    // https://github.com/kth-competitive-programming/kactl/blob/main/content/graph/WeightedMatching.h
    pair<int, vector<int>> hungarian(const vector<vector<int>> &a) {  // Time: O(n^2 * m), Space: O(n + m)
        if (a.empty()) return {0, {}};
        int n = size(a) + 1, m = size(a[0]) + 1;
        vector<int> u(n), v(m), p(m), ans(n - 1);
        for (int i = 1; i < n; ++i) {
            p[0] = i;
            int j0 = 0; // add "dummy" worker 0
            vector<int> dist(m, numeric_limits<int>::max()), pre(m, -1);
            vector<bool> done(m + 1);
            do { // dijkstra
                done[j0] = true;
                int i0 = p[j0], j1, delta = numeric_limits<int>::max();
                for (int j = 1; j < m; ++j) {
                    if (!done[j]) {
                        auto cur = a[i0 - 1][j - 1] - u[i0] - v[j];
                        if (cur < dist[j]) dist[j] = cur, pre[j] = j0;
                        if (dist[j] < delta) delta = dist[j], j1 = j;
                    }
                }
                for (int j = 0; j < m; ++j) {
                    if (done[j]) u[p[j]] += delta, v[j] -= delta;
                    else dist[j] -= delta;
                }
                j0 = j1;
            } while (p[j0]);
            while (j0) { // update alternating path
                int j1 = pre[j0];
                p[j0] = p[j1], j0 = j1;
            }
        }
        for (int j = 1; j < m; ++j) if (p[j]) ans[p[j] - 1] = j - 1;
        return {-v[0], ans}; // min cost
    }
};

// Time:  O(r + (n * m) * 2^n), r = max(x for row in grid for x in row)
// Space: O(r + n * m + 2^n)
// dp, bitmasks
class Solution2 {
public:
    int maxScore(vector<vector<int>>& grid) {
        int mx = 0;
        for (const auto& row : grid) {
            mx = max(mx, ranges::max(row));
        }
        vector<unordered_set<int>> lookup(mx);
        for (int i = 0; i < size(grid); ++i) {
            for (int j = 0; j < size(grid[0]); ++j) {
                lookup[grid[i][j] - 1].emplace(i);
            }
        }
        vector<int> dp(1 << size(grid), numeric_limits<int>::min());
        dp[0] = 0;
        for (int x = 0; x < mx; ++x) {
            if (empty(lookup[x])) {
                continue;
            }
            for (int mask = size(dp) - 1; mask >= 0; --mask) {
                for (const auto& i : lookup[x]) {
                    if (mask & (1 << i)) {
                        continue;
                    }
                    dp[mask | (1 << i)] = max(dp[mask | (1 << i)], dp[mask] + (x + 1));
                }
            }
        }
        return ranges::max(dp);
    }
};

