            int result = 0, right = numeric_limits<int>::min();
            for (const auto& x : intervals) {
                if (x[0] <= right) {
                    ++result;
                } else {
                    right = x[1];
                }
            }
            return result;
        };

        vector<char> cnt(26);
        vector<int> lookup1(26, -1), lookup2(26, -1);
        for (int i = 0; i < size(s); ++i) {
            ++cnt[s[i] - 'a'];
            if (lookup1[s[i] - 'a'] == -1) {
