// Time:  O(r + n * c)
// Space: O(n)

class Solution {
public:
    int wordsTyping(vector<string>& sentence, int rows, int cols) {
        vector<int> wc(sentence.size());
        for (int i = 0; i < sentence.size(); ++i) {
            wc[i] = wordsFit(sentence, i, cols);
        }

        int words = 0, start = 0;
        for (int i = 0; i < rows; ++i) {
            words += wc[start];
            start = (start + wc[start]) % sentence.size();
        }
        return words / sentence.size();
    }

private:
    int wordsFit(const vector<string>& sentence, int start, int cols) {
        if (sentence[start].length() > cols) {
            return 0;
        }

        int sum = sentence[start].length(), count = 1;
        for (int i = (start + 1) % sentence.size();
             sum + 1 + sentence[i].length() <= cols;
             i = (i + 1) % sentence.size()) {
            sum += 1 + sentence[i].length();
            ++count;
        }
        return count;
    }
};

kamyu-c-sentence-similarity-ii-0e8n08m:
// Time:  O(n + p)
// Space: O(p)

class Solution {
public:
    bool areSentencesSimilarTwo(vector<string>& words1, vector<string>& words2, vector<pair<string, string>> pairs) {
        if (words1.size() != words2.size()) {
            return false;
        }
        unordered_map<string, int> lookup;
        UnionFind union_find(2 * pairs.size());
        for (const auto& pair : pairs) {
            if (!lookup.count(pair.first)) {
                lookup.emplace(pair.first, lookup.size());
            }
            if (!lookup.count(pair.second)) {
                lookup.emplace(pair.second, lookup.size());
            }
            union_find.union_set(lookup[pair.first], lookup[pair.second]);
        }
        for (int i = 0; i < words1.size(); ++i) {
            if (words1[i] != words2[i] && 
                (!lookup.count(words1[i]) || !lookup.count(words2[i]) ||
                union_find.find_set(lookup[words1[i]]) != 
                union_find.find_set(lookup[words2[i]]))) {
                return false;
            }
        }
        return true;
    }

private:
    class UnionFind {
        public:
            UnionFind(const int n) : set_(n) {
                iota(set_.begin(), set_.end(), 0);
            }

            int find_set(const int x) {
               if (set_[x] != x) {
                   set_[x] = find_set(set_[x]);  // Path compression.
               }
               return set_[x];
            }

            bool union_set(const int x, const int y) {
                int x_root = find_set(x), y_root = find_set(y);
                if (x_root == y_root) {
                    return false;
                }
                set_[min(x_root, y_root)] = max(x_root, y_root);
                return true;
            }

        private:
            vector<int> set_;
    };
};

