class Solution {
public:
    vector<int> sequentialDigits(int low, int high) {
        vector<int> result;
        queue<int> q{{1, 2, 3, 4, 5, 6, 7, 8}};
        while (!q.empty()) {
            const auto num = q.front(); q.pop();
            if (num > high) {
                continue;
            }
            if (low <= num) {
                result.emplace_back(num);
