// Time:  O(n^2)
// Space: O(n^2)

// bfs
class Solution {
public:
    vector<int> shortestDistanceAfterQueries(int n, vector<vector<int>>& queries) {
        vector<vector<int>> adj(n);
        for (int u = 0; u + 1 < n; ++u) {
            adj[u].emplace_back(u + 1);
        }
        vector<int> dist(n);
        iota(begin(dist), end(dist), 0);
        const auto& bfs = [&](int u, int v) {
            adj[u].emplace_back(v);
            vector<int> q = {u};
            while (!empty(q)) {
                vector<int> new_q;
                for (const auto& u : q) {
                    for (const auto& v : adj[u]) {
                        if (dist[u] + 1 >= dist[v]) {
                            continue;
                        }
                        dist[v] = dist[u] + 1;
                        new_q.emplace_back(v);
                    }
                }
                q = move(new_q);
            }
            return dist[n - 1];
        };

        vector<int> result;
        result.reserve(n);
        for (const auto& q : queries) {
            result.emplace_back(bfs(q[0], q[1]));
        }
        return result;
    }
};

// Time:  O(n^2 * logn)
// Space: O(n^2)
// dijkstra's algorithm
class Solution2 {
public:
    vector<int> shortestDistanceAfterQueries(int n, vector<vector<int>>& queries) {
        vector<vector<pair<int, int>>> adj(n);
        for (int u = 0; u + 1 < n; ++u) {
            adj[u].emplace_back(u + 1, 1);
        }
        vector<int> dist(n);
        iota(begin(dist), end(dist), 0);
        const auto& dijkstra = [&](int u, int v) {
            adj[u].emplace_back(v, 1);
            priority_queue<pair<int, int>, vector<pair<int, int>>, greater<pair<int, int>>> min_heap;
            min_heap.emplace(dist[u], u);
            while (!empty(min_heap)) {
                const auto [curr, u] = min_heap.top(); min_heap.pop();
                if (curr > dist[u]) {
                    continue;
                }
                for (const auto& [v, w] : adj[u]) {
                    if (curr + w >= dist[v]) {
                        continue;
                    }
                    dist[v] = curr + w;
                    min_heap.emplace(dist[v], v);
                }
            }
            return dist[n - 1];
        };

        vector<int> result;
        result.reserve(n);
        for (const auto& q : queries) {
            result.emplace_back(dijkstra(q[0], q[1]));
        }
        return result;
    }
};

// Time:  O(nlogn)
// Space: O(n)

// bst
class Solution {
public:
    vector<int> shortestDistanceAfterQueries(int n, vector<vector<int>>& queries) {
        vector<int> result;
        set<int> bst;
        for (int i = 0; i < n; ++i) {
            bst.emplace(i);
        }
        for (const auto& q : queries) {
            auto jt = bst.lower_bound(q[1]);
            for (auto it = bst.upper_bound(q[0]); it != jt; it = bst.erase(it));
            result.emplace_back(size(bst) - 1);
        }
        return result;
    }
};

kamyu-c-shortest-distance-from-all-build:
// Time:  O(k * m * n), k is the number of the buildings
// Space: O(m * n)

class Solution {
public:
    int shortestDistance(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size(), cnt = 0;
        vector<vector<int>> dists(m, vector<int>(n)), cnts(m, vector<int>(n));
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] == 1) {
                    ++cnt;
                    BFS(grid, i, j, &dists, &cnts);
                }
            }
        }

        int shortest = numeric_limits<int>::max();
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (dists[i][j] < shortest && cnts[i][j] == cnt) {
                    shortest = dists[i][j];
                }
            }
        }

        return shortest != numeric_limits<int>::max() ? shortest : -1;
    }

    void BFS(const vector<vector<int>>& grid, int x, int y,
             vector<vector<int>> *dists, vector<vector<int>> *cnts) {
        int dist = 0, m = grid.size(), n = grid[0].size();
        vector<vector<bool>> visited(m, vector<bool>(n));

        vector<pair<int, int>> pre_level{{x, y}}, cur_level;
        visited[x][y] = true;
        while (!pre_level.empty()) {
            ++dist;
            cur_level.clear();
            for (const auto& p : pre_level) {
                int i, j;
                tie(i, j) = p;
                const vector<pair<int, int>> directions{{0, -1}, {0, 1},
                                                        {-1, 0}, {1, 0}};
                for (const auto& d : directions) {
                    const int I = i + d.first, J = j + d.second;
                    if (0 <= I && I < m && 0 <= J && J < n &&
                        grid[I][J] == 0 && !visited[I][J]) {
                        (*dists)[I][J] += dist;
                        ++(*cnts)[I][J];
                        cur_level.push_back({I, J});
                        visited[I][J] = true;
                    }
                }
            }
            swap(pre_level, cur_level);
        }
    }
};

