                if (v == p) {
                    continue;
                }
                lookup[v] = w;
                dfs(v, u, d + w);
            }
            R[u] = cnt;
        };

        dfs(0, -1, 0);
        BIT bit(n);
        vector<int> result;
        for (const auto& q : queries) {
            if (q[0] == 1) {
