                tie(i, j) = q.front(); q.pop();
                if (0 <= i && i < grid.size() &&
                    0 <= j && j < grid[0].size() &&
                    !grid[i][j]) {
                    grid[i][j] = 1;
                    if (i == grid.size() - 1 && j == grid.size() - 1) {
                        return result;
                    }
                    for (const auto& dir : directions) {
                        next_depth.emplace(i + dir.first, j + dir.second);
                    }
                }
            }
            q = move(next_depth);
        }
        return -1;
    }
};

kamyu-c-shortest-path-to-get-all-keys-0g:
// Time:  O(k*r*c + |E|log|V|) = O(k*r*c + (k*|V|)*log|V|)
//                             = O(k*r*c + (k*(k*2^k))*log(k*2^k))
//                             = O(k*r*c + (k*(k*2^k))*(logk + k*log2))
//                             = O(k*r*c + (k*(k*2^k))*k)
//                             = O(k*r*c + k^3*2^k)
// Space: O(|V|) = O(k*2^k)

class Solution {
public:
    int shortestPathAllKeys(vector<string>& grid) {   
        unordered_map<char, pair<int, int>> locations;
        for (int r = 0; r < grid.size(); ++r) {
            for (int c = 0; c < grid[0].size(); ++c) {
                if (string(".#").find(grid[r][c]) == string::npos) {
                    locations[grid[r][c]] = make_pair(r, c);
                }
            }
        }
        unordered_map<char, unordered_map<char, int>> dists;
        for (const auto& kvp : locations) {
            dists[kvp.first] = bfs(grid, kvp.first, locations);
        }

        // Dijkstra's algorithm
        using T = tuple<int, char, int>;
        priority_queue<T, vector<T>, greater<T>> min_heap;
        min_heap.emplace(0, '@', 0);
        unordered_map<char, unordered_map<int, int>> best;
        best['@'][0] = 0;
        int count = 0;
        for (const auto& kvp : locations) {
            if (islower(kvp.first)) {
                ++count;
            }
        }
        uint32_t target_state = (1 << count) - 1;
        while (!min_heap.empty()) {
            int cur_d, state;
            char place;
            tie(cur_d, place, state) = min_heap.top(); min_heap.pop();
            if (best.count(place) &&
                best[place].count(state) &&
                best[place][state] < cur_d) {
                continue;
            }
            if (state == target_state) {
                return cur_d;
            }
            for (const auto& kvp : dists[place]) {
                int dest, d;
                tie(dest, d) = kvp;
                auto next_state = state;
                if (islower(dest)) {
                    next_state |= (1 << (dest - 'a'));
                } else if (isupper(dest)) {
                    if (!(state & (1 << (dest - 'A')))) {
                        continue;
                    }
                }
                if (!best.count(dest) ||
                    !best[dest].count(next_state) ||
                    cur_d + d < best[dest][next_state]) {
                    best[dest][next_state] = cur_d + d;
                    min_heap.emplace(cur_d + d, dest, next_state);
                }
            }
        }
        return -1;
    }

private:
    unordered_map<char, int> bfs(const vector<string>&grid,
                                 char source,
                                 const unordered_map<char, pair<int, int>>& locations) {
        static const vector<pair<int, int>> directions{{0, -1}, {0, 1},
                                                       {-1, 0}, {1, 0}};
        int r, c;
        tie(r, c) = locations.at(source);
        vector<vector<bool>> lookup(grid.size(), vector<bool>(grid[0].size()));
        lookup[r][c] = true;
        queue<tuple<int, int, int>> q;
        q.emplace(r, c, 0);
        unordered_map<char, int> dist;
        while (!q.empty()) {
            int r, c, d;
            tie(r, c, d) = q.front(); q.pop();
            if (source != grid[r][c] && grid[r][c] != '.') {
                dist[grid[r][c]] = d;
                continue;
            }
            for (const auto& dir : directions) {
                int cr = r + dir.first, cc = c + dir.second;
                if (!((0 <= cr && cr < grid.size()) &&
                      (0 <= cc && cc < grid[0].size()))) {
                         continue;
                }
                if (grid[cr][cc] != '#' && !lookup[cr][cc]) {
                    lookup[cr][cc] = true;
                    q.emplace(cr, cc, d + 1);
                }
            }
        }
        return dist ;
    }
};

kamyu-c-shortest-path-to-get-food-03jodk:
// Time:  O(m * n)
// Space: O(m + n)

class Solution {
public:
    int getFood(vector<vector<char>>& grid) {
        static const vector<pair<int, int>> directions{{0, 1}, {1, 0}, {0, -1}, {-1, 0}};

        vector<pair<int, int>> q;
        for (int r = 0; r < size(grid); ++r) {
            for (int c = 0; c < size(grid[0]); ++c) {
                if (grid[r][c] == '*') {
                    q.emplace_back(r, c);
                    break;
                }
            }
        }

        int result = 0;
        while (!empty(q)) {
            ++result;
            vector<pair<int, int>> new_q;
            for (const auto& [r, c] : q) {
                for (const auto& [dr, dc] : directions) {
                    int nr = r + dr, nc = c + dc;
                    if (!(0 <= nr && nr < size(grid) &&
                          0 <= nc && nc < size(grid[0]) &&
                          grid[nr][nc] != 'X')) {
                        continue;
                    }
                    if (grid[nr][nc] == '#') {
                        return result;
                    }
                    grid[nr][nc] = 'X';
                    new_q.emplace_back(nr, nc);
                }
            }
            q = move(new_q);
        }
        return -1;
    }
};

kamyu-c-shortest-path-visiting-all-nodes:
// Time:  O(n * 2^n)
// Space: O(n * 2^n)

class Solution {
public:
    int shortestPathLength(vector<vector<int>>& graph) {
        static const auto& INF = numeric_limits<int>::max();
        vector<vector<int>> dp(1 << graph.size(),
                               vector<int>(graph.size(), INF));
        queue<pair<int, int>> q;
        for (int i = 0; i < graph.size(); ++i) {
            dp[1 << i][i] = 0;
            q.emplace(1 << i, i);
        }
        while (!q.empty()) {
            int state, node;
            tie(state, node) = q.front(); q.pop();
            auto steps = dp[state][node];
            for (const auto& nei : graph[node]) {
                auto new_state = state | (1 << nei);								
                if (dp[new_state][nei] == INF) {
                    dp[new_state][nei] = steps + 1;
                    q.emplace(new_state, nei);
                }
            }
        }
        return *min_element(dp.back().cbegin(), dp.back().cend());
    }
};

kamyu-c-shortest-path-with-alternating-c:
// Time:  O(n + e), e is the number of red and blue edges
// Space: O(n + e)

class Solution {
public:
    vector<int> shortestAlternatingPaths(int n, vector<vector<int>>& red_edges, vector<vector<int>>& blue_edges) {
        vector<vector<unordered_set<int>>> neighbors(n, vector<unordered_set<int>>(2));
        for (const auto& edge : red_edges) {
            neighbors[edge[0]][0].emplace(edge[1]);
        }
        for (const auto& edge : blue_edges) {
            neighbors[edge[0]][1].emplace(edge[1]);
        }
        const auto& INF = max(2 * n - 3, 0) + 1;
        vector<vector<int>> dist(n, vector<int>(2, INF));
        dist[0] = {0, 0};
        queue<pair<int, int>> q({{0, 0}, {0, 1}});
        while (!q.empty()) {
            int i, c;
            tie(i, c) = q.front(); q.pop();
            for (const auto& j : neighbors[i][c]) {
                if (dist[j][c] != INF) {
                    continue;
                }
                dist[j][c] = dist[i][1 ^ c] + 1;
                q.emplace(j, 1 ^ c);
            }
        }
        vector<int> result;
        for (const auto& d : dist) {
            const auto& x = *min_element(d.cbegin(), d.cend());
            result.emplace_back((x != INF) ? x : -1);
        }
        return result;
    }
};

kamyu-c-shortest-path-with-at-most-k-con:
// Time:  O(e * k * log(n * k))
// Space: O(n * k + e)

// dijkstra's algorithms
class Solution {
public:
    int shortestPath(int n, vector<vector<int>>& edges, string labels, int k) {
        static const auto& INF = numeric_limits<int>::max();

        vector<vector<pair<int, int>>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].emplace_back(e[1], e[2]);
        }
        vector<vector<int>> dist(n, vector<int>(k, INF));
        dist[0][0] = 0;
        using T = tuple<int, int, int>;
        priority_queue<T, vector<T>, greater<T>> min_heap;
        min_heap.emplace(dist[0][0], 0, 0);
        while (!empty(min_heap)) {
            const auto [d, u, c] = min_heap.top(); min_heap.pop();
            if (d > dist[u][c]) {
                continue;
            }
            if (u == n - 1) {
                return d;
            }
            for (const auto& [v, w] : adj[u]) {
                const auto& nc = labels[v] == labels[u] ? c + 1 : 0;
                if (!(nc < k && d + w < dist[v][nc])) {
                    continue;
                }
                dist[v][nc] = d + w;
                min_heap.emplace(dist[v][nc], v, nc);
            }
        }
        return -1;
    }
};

kamyu-c-shortest-string-that-contains-th:
// Time:  O(l)
// Space: O(l)

// brute force, longest prefix suffix, kmp algorithm
class Solution {
public:
    string minimumString(string a, string b, string c) {
        const auto& getPrefix = [](const string& pattern) {
            vector<int> prefix(size(pattern), -1);
            int j = -1;
            for (int i = 1; i < size(pattern); ++i) {
                while (j != -1 && pattern[j + 1] != pattern[i]) {
                    j = prefix[j];
                }
                if (pattern[j + 1] == pattern[i]) {
                    ++j;
                }
                prefix[i] = j;
            }
            return prefix;
        };

        const auto& KMP = [&](const string& text, const string& pattern) {
            const vector<int> prefix = getPrefix(pattern);
            int j = -1;
            for (int i = 0; i < size(text); ++i) {
                while (j > -1 && pattern[j + 1] != text[i]) {
                    j = prefix[j];
                }
                if (pattern[j + 1] == text[i]) {
                    ++j;
                }
                if (j == size(pattern) - 1) {
                    return i - j;
                }
            }
            return -1;
        };

        const auto& merge = [&](const auto& a, const auto& b) {
            if (KMP(b, a) != -1) {
                return b;
            }
            const auto& prefix = getPrefix(b + "#" + a);
            const auto& l = prefix.back() + 1;  // longest prefix suffix length
            return a + b.substr(l);
        };

        vector<string> result = {
            merge(a, merge(b, c)), merge(a, merge(c, b)),
            merge(b, merge(a, c)), merge(b, merge(c, a)),
            merge(c, merge(a, b)), merge(c, merge(b, a))
        };
        return *min_element(cbegin(result), cend(result), [](const auto& a, const auto& b) {
            return size(a) != size(b) ? size(a) < size(b) : a < b;
        });
    }
};

// Time:  O(l^2)
// Space: O(l)
// brute force
class Solution2 {
public:
    string minimumString(string a, string b, string c) {
        const auto& merge = [](const auto& a, const auto& b) {
            if (b.find(a) != string::npos) {
                return b;
            }
            int l = min(size(a), size(b));
            for (; l >= 0; --l) {
                int i = (size(a) - l), j = 0;
                for (; j < l; ++i, ++j) {
                    if (a[i] != b[j]) {
                        break;
                    }
                }
                if (j == l) {
                    break;
                }
            }
            return a + b.substr(l);
        };

        vector<string> result = {
            merge(a, merge(b, c)), merge(a, merge(c, b)),
            merge(b, merge(a, c)), merge(b, merge(c, a)),
            merge(c, merge(a, b)), merge(c, merge(b, a))
        };
        return *min_element(cbegin(result), cend(result), [](const auto& a, const auto& b) {
            return size(a) != size(b) ? size(a) < size(b) : a < b;
        });
    }
};

