kamyu-c-shortest-subarray-with-sum-at-le:
// Time:  O(n)
// Space: O(n)

class Solution {
public:
    int shortestSubarray(vector<int>& A, int K) {
        vector<int> accumulated_sum(A.size() + 1, 0);
        partial_sum(A.cbegin(), A.cend(), next(accumulated_sum.begin()), plus<int>());

        int result = numeric_limits<int>::max();
        deque<int> mono_increasing_q;
        for (int i = 0; i < accumulated_sum.size(); ++i) {
            while (!mono_increasing_q.empty() &&
                   accumulated_sum[i] <= accumulated_sum[mono_increasing_q.back()]) {
                mono_increasing_q.pop_back();
            }
            while (!mono_increasing_q.empty() &&
                   accumulated_sum[i] - accumulated_sum[mono_increasing_q.front()] >= K) {
                result = min(result, i - mono_increasing_q.front());
                mono_increasing_q.pop_front();
            }
            mono_increasing_q.emplace_back(i);
        }
        return result != numeric_limits<int>::max() ? result : -1;
    }
};

kamyu-c-shortest-uncommon-substring-in-a:
// Time:  O(n * l^2)
// Space: O(t)

// trie
class Solution {
private:
    class Trie {
    public:
        Trie() {
             new_node();
         }

        void add(const string& s, int d) {
            for (int i = 0; i < size(s); ++i) {
                int curr = 0;
                for (int j = i; j < size(s); ++j) {
                    const int x = s[j] - 'a';
                    if (nodes_[curr][x] == -1) {
                        nodes_[curr][x] = new_node();
                    }
                    curr = nodes_[curr][x];
                    cnts_[curr] += d;
                }
            }
        }

        string query(const string& s) {
            pair<int, string> result = {numeric_limits<int>::max(), ""};
            for (int i = 0; i < size(s); ++i) {
                int curr = 0;
                for (int j = i; j < size(s); ++j) {
                    const int x = s[j] - 'a';
                    curr = nodes_[curr][x];
                    if (cnts_[curr] == 0) {
                        result = min(result, {j - i + 1, s.substr(i, j - i + 1)});
                        break;
                    }
                }
            }
            return result.second;
        }

    private:
        int new_node() {
            nodes_.emplace_back(26, -1);
            cnts_.emplace_back(0);
            return size(nodes_) - 1;
        }

        vector<vector<int>> nodes_;
        vector<int> cnts_;
    };

public:
    vector<string> shortestSubstrings(vector<string>& arr) {
        Trie trie;
        for (const auto& x : arr) {
            trie.add(x, +1);
        }
        vector<string> result;
        for (const auto& x: arr) {
            trie.add(x, -1);
            result.emplace_back(trie.query(x));
            trie.add(x, +1);
        }
        return result;
    }
};

kamyu-c-shortest-unsorted-continuous-sub:
// Time:  O(n)
// Space: O(1)

class Solution {
public:
    int findUnsortedSubarray(vector<int>& nums) {
        const auto n = nums.size();
        auto left = -1, right = -2;
        auto max_from_left = nums[0], min_from_right = nums.back();
        for (int i = 1; i < n; ++i) {
            max_from_left = max(max_from_left, nums[i]);
            min_from_right = min(min_from_right, nums[n - 1 - i]);
            if (nums[i] < max_from_left) {
                right = i;
            }
            if (nums[n - 1 - i] > min_from_right) {
                left = n - 1 - i;
            }
        }
        return right - left + 1;
    }
};

