        string nums = to_string(abs(num));
        if (sign == 1) {
            sort(begin(nums), end(nums));
        } else {
            sort(rbegin(nums), rend(nums));
        }
        auto it = find_if(begin(nums), end(nums), [](const auto& x) {
            return x != '0';
        });
        if (it != end(nums)) {
            swap(nums[0], *it);
        }
        return sign * stoll(nums);
    }
};

