                for (; !lookup[nums[i]]; ++l, i = index(nums[i])) {
                    lookup[nums[i]] = true;
                }
                --result;
                if (l >= 2) {
                    result += 2;
                }
            }
            return result - 2 * static_cast<int>(nums[d * (size(nums) - 1)] != 0);
        };

        return min(min_moves(0), min_moves(1));
    }
};

