            for (int base = 1; x; x /= 10, base *= 10) {
                result += mapping[x % 10] * base;
            }
            return result;
        };

        vector<pair<int, int>> order;
        for (int i = 0; i < size(nums); ++i) {
            order.emplace_back(transform(nums[i]), i);
