kamyu-c-sort-transformed-array-0sr1l96:
// Time:  O(n)
// Space: O(1)

class Solution {
public:
    vector<int> sortTransformedArray(vector<int>& nums, int a, int b, int c) {
        const auto f = [](int x, int a, int b, int c) {
            return a * x * x + b * x + c;
        };

        vector<int> result;
        if (nums.empty()) {
            return result;
        }

        int left = 0, right = nums.size() - 1;
        int d = a > 0 ? -1 : 1;
        while (left <= right) {
            if (d * f(nums[left], a, b, c) < d * f(nums[right], a, b, c)) {
                result.emplace_back(f(nums[left++], a, b, c));
            } else {
                result.emplace_back(f(nums[right--], a, b, c));
            }
        }
        if (d == -1) {
            reverse(result.begin(), result.end());
        }

        return result;
    }
};

kamyu-c-sort-vowels-by-frequency-1lug8ic:
// Time:  O(n)
// Space: O(1)

// freq table, sort
class Solution {
public:
    string sortVowels(string s) {
        static const string VOWELS = "aeiou";

        unordered_map<char, vector<int>> cnt;
        for (int i = 0; i < size(s); ++i) {
            if (VOWELS.find(s[i]) == string::npos) {
                continue;
            }
            if (!cnt.count(s[i])) {
                cnt[s[i]] = vector<int>{0, i};
            }
            ++cnt[s[i]][0];
        }
        vector<tuple<char, int, int>> sorted_cnt;
        for (const auto& [k, v] : cnt) {
            sorted_cnt.emplace_back(k, v[0], v[1]);
        }
        ranges::sort(sorted_cnt, [](const auto& a, const auto& b) {
            return get<1>(a) == get<1>(b) ? get<2>(a) > get<2>(b) : get<1>(a) < get<1>(b);
        });
        for (int i = 0; i < size(s); ++i) {
            if (VOWELS.find(s[i]) == string::npos) {
                continue;
            }
            s[i] = get<0>(sorted_cnt.back());
            if (!(--get<1>(sorted_cnt.back()))) {
                sorted_cnt.pop_back();
            }
        }
        return s;
    }
};

kamyu-c-sort-vowels-in-a-string-0imd14d:
// Time:  O(n)
// Space: O(1)

// counting sort
class Solution {
public:
    string sortVowels(string s) {
        const auto& inplace_counting_sort = [](vector<int> *nums, bool is_reverse) {
            if (empty(*nums)) {
                return;
            }
            const int max_num = *max_element(cbegin(*nums), cend(*nums));
            vector<int> count(max_num + 1);
            for (const auto& num : *nums) {
                ++count[num];
            }
            for (int i = 1; i < size(count); ++i) {
                count[i] += count[i - 1];
            }
            for (int i = size(*nums) - 1; i >= 0; --i) {  // inplace but unstable sort
                while ((*nums)[i] >= 0) {
                    --count[(*nums)[i]];
                    const int j = count[(*nums)[i]];
                    tie((*nums)[i], (*nums)[j]) = pair((*nums)[j], ~(*nums)[i]);
                }
            }
            for (auto& num : *nums) {
                num = ~num;  // restore values
            }
            if (is_reverse) {  // unstable sort
                reverse(begin(*nums), end(*nums));
            }
        };

        static const string VOWELS = "AEIOUaeiou";
        unordered_map<char, int> LOOKUP;
        for (int i = 0; i < size(VOWELS); ++i) {
            LOOKUP[VOWELS[i]] = i;
        }
        vector<int> vowels;
        for (const auto& x : s) {
            if (LOOKUP.count(x)) {
                vowels.push_back(LOOKUP[x]);
            }
        }
        inplace_counting_sort(&vowels, true);
        string result;
        for (const auto& x : s) {
            if (LOOKUP.count(x)) {
                result.push_back(VOWELS[vowels.back()]);
                vowels.pop_back();
            } else {
                result.push_back(x);
            }
        }
        return result;
    }
};

