// Time:  f(n) = k * f(n/k) + n/k * klogk <= O(logn * nlogk) <= O(n^2)
//        n is the length of S, k is the max number of special strings in each depth
// Space: O(n)

class Solution {
public:
    string makeLargestSpecial(string S) {
        vector<string> result;
        int anchor = 0, count = 0;
        for (int i = 0; i < S.length(); ++i) {
            (S[i] == '1') ? ++count : --count;
            if (count == 0) {
                result.emplace_back("1");
                result.back() += makeLargestSpecial(S.substr(anchor + 1, i - anchor - 1));
                result.back() += "0";
                anchor = i + 1;
            }
        }
        sort(result.begin(), result.end(), greater<string>());
        return accumulate(result.begin(), result.end(), string());
    }
};

kamyu-c-special-permutations-0xqr1ad:
// Time:  O(n^2 * 2^n)
// Space: O(n * 2^n)

// backtracking, memoization
class Solution {
public:
    int specialPerm(vector<int>& nums) {
        static const int MOD = 1e9 + 7;

        vector<vector<int>> lookup(size(nums) + 1, vector<int>(1 << size(nums), -1));
        function<int (int, int)> backtracking = [&](int i, int mask) {
            if (mask == (1 << size(nums)) - 1) {
                return 1;
            }
            if (lookup[i + 1][mask] == -1) {
                int total = 0;
                for (int j = 0; j < size(nums); ++j) {
                    if (mask & (1 << j)) {
                        continue;
                    }
                    if (!(i == -1 || nums[i] % nums[j] == 0 || nums[j] % nums[i] == 0)) {
                        continue;
                    }
                    total = (total + backtracking(j, mask | (1 << j))) % MOD;
                }
                lookup[i + 1][mask] = total;
            }
            return lookup[i + 1][mask];
        };

        return backtracking(-1, 0);
    }
};

