// Time:  precompute: O(max_n), max_n = max(len(nums))
//        runtime:    O(n)
// Space: O(max_n)

// number theory
vector<int64_t> linear_sieve_of_eratosthenes(int64_t n) {  // Time: O(n), Space: O(n)
    vector<int64_t> spf(n + 1, -1);
    vector<int64_t> primes;
    for (int64_t i = 2; i <= n; ++i) {
        if (spf[i] == -1) {
            spf[i] = i;
            primes.emplace_back(i);
        }
        for (const auto& p : primes) {
            if (i * p > n || p > spf[i]) {
                break;
            }
            spf[i * p] = p;
        }
    }
    return spf;
}

static const int MAX_IDX = 1e5 - 1;
const auto& SPF = linear_sieve_of_eratosthenes(MAX_IDX);
class Solution {
public:
    long long splitArray(vector<int>& nums) {
        int64_t result = 0;
        for (int i = 0; i < size(nums); ++i) {
            result += SPF[i] == i ? nums[i] : -nums[i];
        }
        return abs(result);
    }
};

kamyu-c-split-array-into-consecutive-sub:
// Time:  O(n)
// Space: O(1)

class Solution {
public:
    bool isPossible(vector<int>& nums) {
        auto pre = numeric_limits<int>::min(), cur = 0;
        auto cnt1 = 0, cnt2 = 0, cnt3 = 0;  // count of each length ending at cur
        for (int i = 0; i < nums.size(); pre = cur) {
            auto cnt = 0;
            for (cur = nums[i]; i < nums.size() && cur == nums[i]; ++cnt, ++i);

            if (cur != pre + 1) {
                if (cnt1 != 0 || cnt2 != 0) {
                    return false;
                }
                tie(cnt1, cnt2, cnt3) = make_tuple(cnt, 0, 0);
            } else {
                if (cnt < cnt1 + cnt2) {
                    return false;
                }
                tie(cnt1, cnt2, cnt3) = make_tuple(max(0, cnt - (cnt1 + cnt2 + cnt3)),
                                                   cnt1,
                                                   cnt2 + min(cnt3, cnt - (cnt1 + cnt2)));
            }
        }
        return cnt1 == 0 && cnt2 == 0;
    }
};

kamyu-c-split-array-into-fibonacci-seque:
// Time:  O(n^3)
// Space: O(n)

class Solution {
public:
    vector<int> splitIntoFibonacci(string S) {
        for (int i = 0, a = 0; i + 2 < S.length(); ++i) {
            a = 10 * a + S[i] - '0';
            for (int j = i + 1, b = 0; j + 1 < S.length(); ++j) {
                b = 10 * b + S[j] - '0';
                vector<int> fib = {a, b};
                int k = j + 1;
                while (k < S.length()) {
                    if (fib[fib.size() - 2] > numeric_limits<int>::max() - fib[fib.size() - 1]) {
                        break;
                    }
                    auto c = fib[fib.size() - 2] + fib[fib.size() - 1];
                    auto l = startswith(S, k, c);
                    if (l == 0) {
                        break;
                    }
                    fib.emplace_back(c);
                    k += l;
                }
                if (k == S.length()) {
                    return fib;
                }
                if (b == 0) {
                    break;
                }
            }
            if (a == 0) {
                break;
            }
        }
        return {};
    }

private:
    int startswith(const string& S, int k, int x) {
        int y = 0;
        for (int i = k; i < S.length(); ++i) {
            y = 10 * y + S[i] - '0';
            if (y == x) {
                return i - k + 1;
            } else if (y > x) {
                break;
            }
        }
        return 0;
    }
};

