kamyu-c-split-array-largest-sum-0mjf8lv:
// Time:  O(nlogs), s is the sum of nums
// Space: O(1)

class Solution {
public:
    int splitArray(vector<int>& nums, int m) {
        int64_t left = *max_element(cbegin(nums), cend(nums));
        int64_t right = accumulate(cbegin(nums), cend(nums), 0LL);
        while (left <= right) {
            const auto mid = left + (right - left) / 2;
            if (check(nums, m, mid)) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }
        return left;
    }

private:
    bool check(vector<int>& nums, int m, int64_t total) {
        int cnt = 1;
        int64_t curr_sum = 0;
        for (const auto& num : nums) {
            curr_sum += num;
            if (curr_sum > total) {
                curr_sum = num;
                ++cnt;
            }
        }
        return cnt <= m;
    }
};

