    long long splitArray(vector<int>& nums) {
        int64_t left = 0, i = 0;
        while (i + 1 < size(nums) && nums[i] < nums[i + 1]) {
            left += nums[i++];
        }
        int64_t right = 0, j = size(nums) - 1;;
        while (j - 1 >= 0 && nums[j] < nums[j - 1]) {
            right += nums[j--];
        }
        if (j - i + 1 >= 3) {
            return -1;
        }
        if (j - i + 1 == 2) {
            return abs((right + nums[j]) - (left + nums[i]));
        }
        return min(abs(right - (left + nums[i])), abs((right + nums[j]) - left));
    }
};

kamyu-c-split-array-with-same-average-1n:
// Time:  O(n^4)
// Space: O(n^3)

class Solution {
public:
    bool splitArraySameAverage(vector<int>& A) {
        const int n = A.size();
        const int sum = accumulate(A.cbegin(), A.cend(), 0);
        if (!possible(n, sum)) {
            return false;
        }

        vector<unordered_set<int>> sums(n / 2 + 1);
        sums[0].emplace(0);
        for (const auto& num: A) {                      // O(n) times
            for (int i = n / 2; i >= 1; --i) {          // O(n) times
                for (const auto& prev : sums[i - 1]) {  // O(1) + O(2) + ... O(n/2) = O(n^2) times
                    sums[i].emplace(prev + num);
                }
            }
        }
        for (int i = 1; i <= n / 2; ++i) {
            if (sum * i % n == 0 &&
                sums[i].count(sum * i / n)) {
                return true;
            }
        }
        return false;
    }

private:
    bool possible(int n, int sum) {
        for (int i = 1; i <= n / 2; ++i)  {
            if (sum * i % n == 0) {
                return true;
            }
        }
        return false;
    }
};

kamyu-c-split-bst-0dwxogo:
// Time:  O(n)
// Space: O(h)

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode(int x) : val(x), left(NULL), right(NULL) {}
 * };
 */
class Solution {
public:
    vector<TreeNode*> splitBST(TreeNode* root, int V) {
        if (!root) {
            return {nullptr, nullptr};
        } else if (root->val <= V) {
            const auto& result = splitBST(root->right, V);
            root->right = result[0];
            return {root, result[1]};
        } else {
            const auto& result = splitBST(root->left, V);
            root->left = result[1];
            return {result[0], root};
        }
    }
};

