kamyu-c-splitting-a-string-into-descendi:
// Time:  O(n^2)
// Space: O(n)

class Solution {
public:
    bool splitString(string s) {
        return backtracking(s, 0, -1, 0);
    }

private:
    bool backtracking(const string& s, int i, int64_t num, int cnt) {
        if (i == size(s)) {
            return cnt >= 2;
        }
        int64_t new_num = 0;
        for (int j = i; j < size(s); ++j) {
            new_num = new_num * 10 + (s[j] - '0');
            if (new_num >= 1e10) {
                break;
            }
            if (new_num >= num && num >= 0) {
                break;
            }
            if ((num == -1 || (num - 1) == new_num) && backtracking(s, j + 1, new_num, cnt + 1)) {
                return true;
            }
        }
        return false;
    }
};

kamyu-c-sqrtx-0dw5bv2:
// Time:  O(logn)
// Space: O(1)

class Solution {
public:
    int mySqrt(int x) {
        if (x < 2) {
            return x;
        }

        int left = 1, right = x / 2;
        while (left <= right) {
            const auto mid = left + (right - left) / 2;
            if (mid > x / mid) {
                right = mid - 1;
            } else {
                left = mid + 1;
            }
        }

        return left - 1;
    }
};

