// Time:  O(n)
// Space: O(1)

class Solution {
public:
    vector<double> sampleStats(vector<int>& count) {
        const double mi = distance(count.cbegin(), find_if(count.cbegin(), count.cend(), 
                                   [](int x) { return x != 0; }));

        const double ma = count.size() - 1 - 
                          distance(count.crbegin(), find_if(count.crbegin(), count.crend(), 
                                   [](int x) { return x != 0; }));

        const auto& n = accumulate(count.cbegin(), count.cend(), 0);
        double total = 0.0;
        for (int i = 0; i < count.size(); ++i) {
            total += double(i) * count[i];
        }
        const double mean = total / n;

        const double mode = distance(count.cbegin(), max_element(count.cbegin(), count.cend()));

        for (int i = 1; i < count.size(); ++i) {
            count[i] += count[i - 1];
        }
        const auto& median1 = distance(count.cbegin(), lower_bound(count.cbegin(), count.cend(), (n + 1) / 2));
        const auto& median2 = distance(count.cbegin(), lower_bound(count.cbegin(), count.cend(), (n + 2) / 2));
        const double median = (median1 + median2) / 2.0;

        return {mi, ma, mean, median, mode};
    }
};

kamyu-c-step-by-step-directions-from-a-b:
// Time:  O(n)
// Space: O(h)

class Solution {
public:
    string getDirections(TreeNode* root, int startValue, int destValue) {
        auto src = iter_dfs(root, startValue);
        auto dst = iter_dfs(root, destValue);
        while (!empty(src) && !empty(dst) && src.back() == dst.back()) {
            src.pop_back();
            dst.pop_back();
        }
        reverse(begin(dst), end(dst));
        return string(size(src), 'U') + dst;
    }

private:
    string iter_dfs(TreeNode *root, int val) {
        string path;
        vector<tuple<int, TreeNode *, char>> stk = {{1, root, ' '}};
        while (!empty(stk)) {
            auto [step, node, d] = stk.back(); stk.pop_back();
            if (step == 1) {
                if (node->val == val) {
                    reverse(begin(path), end(path));
                    return path;
                }
                for (const auto& child : {node->left, node->right}) {
                    if (!child) {
                        continue;
                    }
                    stk.emplace_back(3, nullptr, ' ');
                    stk.emplace_back(1, child, ' ');
                    stk.emplace_back(2, nullptr, (child == node->left) ? 'L' : 'R');
                }
            } else if (step == 2) {
                path.push_back(d);
            } else if (step == 3) {
                path.pop_back();
            }
        }
        return "";
    }
};

// Time:  O(n)
// Space: O(h)
class Solution2 {
public:
    string getDirections(TreeNode* root, int startValue, int destValue) {
        string src, dst;
        dfs(root, startValue, &src);
        dfs(root, destValue, &dst);
        while (!empty(src) && !empty(dst) && src.back() == dst.back()) {
            src.pop_back();
            dst.pop_back();
        }
        reverse(begin(dst), end(dst));
        return string(size(src), 'U') + dst;
    }

private:
    bool dfs(TreeNode *curr, int val, string *path) {
        if (curr->val == val) {
            return true;
        }
        if (curr->left && dfs(curr->left, val, path)) {
            path->push_back('L');
        } else if (curr->right && dfs(curr->right, val, path)) {
            path->push_back('R');
        }
        return !empty(*path);
    }
};

