kamyu-c-steps-to-make-array-non-decreasi:
// Time:  O(n)
// Space: O(n)

// mono stack, dp
class Solution {
public:
    int totalSteps(vector<int>& nums) {
        vector<int> dp(size(nums));  // dp[i]: number of rounds for nums[i] to remove all the covered elements
         vector<int> stk;
        for (int i = size(nums) - 1; i >= 0; --i) {
            while (!empty(stk) && nums[stk.back()] < nums[i]) {
                dp[i] = max(dp[i] + 1, dp[stk.back()]); stk.pop_back();
            }
            stk.emplace_back(i);
        }
        return *max_element(cbegin(dp), cend(dp));
    }
};

// Time:  O(n)
// Space: O(n)
// mono stack, dp
class Solution2 {
public:
    int totalSteps(vector<int>& nums) {
        vector<int> dp(size(nums));  // dp[i]: number of rounds for nums[i] to be removed
         vector<int> stk;
        for (int i = 0; i < size(nums); ++i) {
            int curr = 0;
            while (!empty(stk) && nums[stk.back()] <= nums[i]) {
                curr = max(curr, dp[stk.back()]); stk.pop_back();
            }
            if (!empty(stk)) {
                dp[i] = curr + 1;
            }
            stk.emplace_back(i);
        }
        return *max_element(cbegin(dp), cend(dp));
    }
};

kamyu-c-stickers-to-spell-word-19gylky:
// Time:  O(T * S^T)
// Space: O(T * S^T)

class Solution {
public:
    int minStickers(vector<string>& stickers, string target) {
        vector<vector<int>> sticker_counts(stickers.size(), vector<int>(26));
        unordered_map<string, int> dp;
        for (int i = 0; i < stickers.size(); ++i) {
            for (const auto& c : stickers[i]) {
                ++sticker_counts[i][c - 'a'];
            }
        }
        dp[""] = 0;
        return minStickersHelper(sticker_counts, target, &dp);
    }

private:
    int minStickersHelper(const vector<vector<int>>& sticker_counts, const string& target,
                          unordered_map<string, int> *dp) {
        if (dp->count(target)) {
            return (*dp)[target];
        }
        int result = numeric_limits<int>::max();
        vector<int> target_count(26);
        for (const auto& c : target) {
            ++target_count[c - 'a'];
        }
        for (const auto& sticker_count : sticker_counts) {
            if (sticker_count[target[0] - 'a'] == 0) {
                continue; 
            }
            string new_target;
            for (int i = 0; i < target_count.size(); ++i) {
                if (target_count[i] - sticker_count[i] > 0) {
                    new_target += string(target_count[i] - sticker_count[i], 'a' + i);
                }
            }
            if (new_target.length() != target.length()) {
                int num = minStickersHelper(sticker_counts, new_target, dp);
                if (num != -1) {
                    result = min(result, 1 + num);
                }
            }
        }
        (*dp)[target] = (result == numeric_limits<int>::max()) ? -1 : result;
        return (*dp)[target];
    }
};

