kamyu-c-stone-game-ix-0p2ho6o:
// Time:  O(n)
// Space: O(1)

class Solution {
public:
    bool stoneGameIX(vector<int>& stones) {
        unordered_map<int, int> count;
        for (const auto& x : stones) {
            ++count[x % 3];
        }
        if (count[0] % 2 == 0) {
            // iff both counts are not zero, then alice takes the least one at first, the remains are deterministic for bob to lose:
            // - assumed count[1] is the least one:
            //   1(,1,2)*,2,(,2)* => bob loses
            //            ^
            // - assumed count[2] is the least one:
            //   2(,2,1)*,1,(,1)* => bob loses
            //            ^
            return count[1] && count[2];
        }
        // iff abs(count[1]-count[2]) >= 3, then alice takes the most one at first, the remains are deterministic for bob to lose:
        // - assumed count[1] is the most one
        //   1(,1,2)*,0,1(,2,1)*,1,(,1)* => bob loses
        //                       ^
        //   1(,1,2)*,1,0,1,(,1)* => bob loses
        //                ^
        // - assumed count[2] is the most one
        //   2(,2,1)*,0,2(,1,2)*,2,(,2)* => bob loses
        //                       ^
        //   2(,2,1)*,2,0,2,(,2)* => bob loses
        //                ^
        return abs(count[1] - count[2]) >= 3;
    }
};

kamyu-c-stone-game-v-0t6mi1v:
// Time:  O(n^2)
// Space: O(n^2)

class Solution {
public:
    int stoneGameV(vector<int>& stoneValue) {
        const int n = stoneValue.size();
        vector<int> prefix(n + 1);
        partial_sum(cbegin(stoneValue), cend(stoneValue), begin(prefix) + 1);

        vector<int> mid(n);
        iota(begin(mid), end(mid), 0);

        vector<vector<int>> dp(n, vector<int>(n));
        for (int i = 0; i < n; ++i) {
            dp[i][i] = stoneValue[i];
        }

        int max_score = 0;
        for (int l = 2; l <= n; ++l) {
            for (int i = 0; i <= n - l; ++i) {
                const int j = i + l - 1;
                while (prefix[mid[i]] - prefix[i] < prefix[j + 1] - prefix[mid[i]]) {
                    ++mid[i];  // Time: O(n^2) in total
                }
                const int p = mid[i];
                max_score = 0;
                if (prefix[p] - prefix[i] == prefix[j + 1] - prefix[p]) {
                    max_score = max(dp[i][p - 1], dp[j][p]);
                } else {
                    if (i <= p - 2) {
                        max_score = max(max_score, dp[i][p - 2]);
                    }
                    if (p <= j) {
                        max_score = max(max_score, dp[j][p]);
                    }
                }
                dp[i][j] = max(dp[i][j - 1], (prefix[j + 1] - prefix[i]) + max_score);
                dp[j][i] = max(dp[j][i + 1], (prefix[j + 1] - prefix[i]) + max_score);
            }
        }
        return max_score;
    }
};


