kamyu-c-subsequence-of-size-k-with-the-l:
// Time:  O(n) on overage
// Space: O(1)

// quick select solution
class Solution {
public:
    long long largestEvenSum(vector<int>& nums, int k) {
        nth_element(begin(nums), begin(nums) + k, end(nums), greater<int>());
        int64_t total = accumulate(begin(nums), begin(nums) + k, 0ll);
        if (total % 2 == 0) {
            return total;
        }
        vector<int> min_k(2, numeric_limits<int>::max());
        for (int i = 0; i < k; ++i) {
            min_k[nums[i] % 2] = min(min_k[nums[i] % 2], nums[i]);
        }
        int64_t result = -1;
        for (int i = k; i < size(nums); ++i) {
            result = max(result, total - min_k[!(nums[i] % 2)] + nums[i]);
        }
        return result;
    }
};

kamyu-c-subsequence-sum-after-capping-el:
// Time:  O(nlogn + n * k + klogn) = O(nlogn + n * k)
// Space: O(k)

// sort, dp, bitmasks
class Solution {
public:
    vector<bool> subsequenceSumAfterCapping(vector<int>& nums, int k) {
        static const int MAX_K = 4000;
        sort(begin(nums), end(nums));
        vector<bool> result(size(nums));
        bitset<MAX_K + 1> dp;
        dp[0] = 1;
        for (int x = 1, i = 0; x <= size(nums); ++x){
            while (i < size(nums) && nums[i] < x) {
                dp |= (dp << nums[i]);
                ++i;
            }
            for (int j = max(k % x, k - (static_cast<int>(size(nums)) - i) * x); j <= k; j += x)
                if (dp[j]) {
                    result[x - 1] = true;
                }
        }
        return result;
    }
};

